        "Selected primary main Results, figure legends and Methods were read in Europe PMC XML. Supplemental movies and full raw datasets were not inspected. Same-cell imaging distinguishes recovery from replacement by nonresponding cells, but the additional molecular/DNA readouts use distinct populations and preparations. The Results describe the Figure 1G HeLa same-cell exposure as 3 hours, whereas Figure 1H population quantification and the default Methods specify 5 hours; those histories and the associated population fractions are not merged. Inducer concentration, cell type and duration must remain separate; recovery does not imply complete repair or a universally reversible state.",
